excels.excel:

EXPORT WITH SHEET="产品质量成本分析", HEADER=true,
    MAPPING={"a":"产品名称","b":"检验数量","c":"不良数量","d":"不良率","e":"单件返工成本","f":"质量成本","g":"控制状态"},
    FORMAT={"b":"#,##0","c":"#,##0","d":"0.00%","e":"#,##0.00","f":"#,##0.00"},
    FORMULAS={
        D2:'C2/B2',F2:'C2*E2',
        D3:'C3/B3',F3:'C3*E3',
        D4:'C4/B4',F4:'C4*E4',
        D5:'C5/B5',F5:'C5*E5',
        D6:'C6/B6',F6:'C6*E6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'C7/B7',F7:'SUM(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        D3:{color:red,bold:true}
    }
